tests:
test({ sr: 'uklanja duplikate brojeva', en: 'removes duplicate numbers' }, () => {
  expect(unique([1, 2, 2, 3, 1])).toEqual([1, 2, 3]);
});
test({ sr: 'radi sa stringovima', en: 'works with strings' }, () => {
  expect(unique(['a', 'a'])).toEqual(['a']);
});
test({ sr: 'prazan niz daje prazan niz', en: 'an empty array gives an empty array' }, () => {
  expect(unique([])).toEqual([]);
});

hiddenTests:
test('keeps the order of first occurrence', () => {
  expect(unique([3, 1, 3, 2, 1])).toEqual([3, 1, 2]);
});
test('does not change the input', () => {
  const input = [1, 1, 2];
  unique(input);
  expect(input).toEqual([1, 1, 2]);
});
test('the number 1 and the string 1 are different values', () => {
  expect(unique([1, '1', 1])).toEqual([1, '1']);
});
test('NaN is treated as one value', () => {
  expect(unique([NaN, NaN])).toEqual([NaN]);
});
